{
  "title": "add-ingestion-version-parameter",
  "request": "Hey, can we make the ingestion version header configurable when creating a LangfuseSpanProcessor? I'd like to pass an `ingestion_version` argument so we can set it to something other than the default "4".",
  "edits": [
    {
      "path": "langfuse/_client/span_processor.py",
      "search": "otel_compression: Optional[Literal["gzip", "none"]] = None,",
      "replace": "otel_compression: Optional[Literal["gzip", "none"]] = None,
        ingestion_version: Optional[str] = None,"
    },
    {
      "path": "langfuse/_client/span_processor.py",
      "search": "default_headers = {
                "Authorization": basic_auth_header,
                "x-langfuse-sdk-name": "python",
                "x-langfuse-sdk-version": langfuse_version,
                "x-langfuse-public-key": public_key,
                "x-langfuse-ingestion-version": "4",
            }",
      "replace": "default_headers = {
                "Authorization": basic_auth_header,
                "x-langfuse-sdk-name": "python",
                "x-langfuse-sdk-version": langfuse_version,
                "x-langfuse-public-key": public_key,
                "x-langfuse-ingestion-version": ingestion_version if ingestion_version is not None else "4",
            }"
    }
  ],
  "test_path": "tests/unit/test_span_processor_ingestion_version.py",
  "test": "import pytest
from langfuse._client import span_processor as span_processor_module
from langfuse._client.span_processor import LangfuseSpanProcessor


def _record_exporter(monkeypatch):
    recorded = {}
    class DummyExporter:
        def __init__(self, endpoint, headers, **kwargs):
            recorded["endpoint"] = endpoint
            recorded["headers"] = headers
    monkeypatch.setattr(span_processor_module, "OTLPSpanExporter", DummyExporter)
    return recorded


def test_ingestion_version_header_default(monkeypatch):
    recorded = _record_exporter(monkeypatch)
    processor = LangfuseSpanProcessor(
        public_key="pk-test",
        secret_key="sk-test",
        base_url="http://example.com",
    )
    try:
        assert recorded["headers"]["x-langfuse-ingestion-version"] == "4"
    finally:
        processor.shutdown()


def test_ingestion_version_header_custom(monkeypatch):
    recorded = _record_exporter(monkeypatch)
    processor = LangfuseSpanProcessor(
        public_key="pk-test",
        secret_key="sk-test",
        base_url="http://example.com",
        ingestion_version="7",
    )
    try:
        assert recorded["headers"]["x-langfuse-ingestion-version"] == "7"
    finally:
        processor.shutdown()
"
}
